tool_calls.command:
cd . && cat > /tmp/probe_keyless_test.go <<'EOF'
package registry

import (
	"errors"
	"strings"
	"testing"
)

// Probe: empty/empty through the REAL HTTP handler + RemoteStore seam.
func TestProbe_KeylessDuplicateThroughHTTPAndRemote(t *testing.T) {
	srv, store := newRemoteTestServer(t) // signing disabled: keyless allowed
	rs := NewRemoteStore(srv.URL, "probe", "")

	if err := rs.Register(&Agent{ID: "kl"}); err != nil {
		t.Fatalf("first keyless register: %v", err)
	}
	err := rs.Register(&Agent{ID: "kl"})
	if err == nil {
		t.Fatal("duplicate keyless register succeeded")
	}
	t.Logf("remote err = %q", err.Error())
	if errors.Is(err, ErrPublicKeyMismatch) {
		t.Fatalf("empty/empty reported as public-key mismatch: %v", err)
	}
	if !errors.Is(err, ErrAgentExists) {
		t.Fatalf("empty/empty not classified as duplicate: %v", err)
	}
	if strings.Contains(err.Error(), "different public key") {
		t.Fatalf("empty/empty carries mismatch wording: %v", err)
	}
	// genuine mismatch still preserved through the same seam
	if err := rs.Register(&Agent{ID: "kl", PublicKey: HexKey(make([]byte, 32))}); err == nil {
		t.Fatal("keyed re-register over keyless succeeded")
	} else {
		t.Logf("keyed-over-keyless err = %q", err.Error())
		if !errors.Is(err, ErrPublicKeyMismatch) {
			t.Fatalf("genuine mismatch lost: %v", err)
		}
	}
	_ = store
}
EOF
cp /tmp/probe_keyless_test.go internal/registry/zz_probe_keyless_test.go && go test -short -count=1 -run TestProbe_KeylessDuplicateThroughHTTPAndRemote -v ./internal/registry/ 2>&1 | tail -20; rm -f internal/registry/zz_probe_keyless_test.go
